namespace mdemangler.datatype.modifier;

using mdemangler;
using mdemangler.datatype.extended;
using mdemangler.functiontype;

/**
 * This class represents an Array Basic data type within a Microsoft mangled symbol.
 */
// TODO: Consider making this an extension of ExtendedDataType (fits with the
// other '_X' types.
// The array type, however, modifies other types...???
// 20230731: note that this class uses a CVMod type, which supports its being a MDModifierType.
public class MDArrayBasicType : MDModifierType {

	public MDArrayBasicType(MDMang dmang) : base(dmang)
    {
	}

	/* @Override */
	protected void parseInternal()
    {
		cvMod.setArrayType();
		base.parseInternal();
	}

	/* @Override */
	protected void insertCVMod(StringBuilder builder) {
		// do nothing.
	}

	/* @Override */
	protected void insertReferredType(StringBuilder builder, bool isArg) {
		StringBuilder arrayBuilder = new StringBuilder();
		arrayBuilder.append("[]");
		MDType dt = this.refType;
		while (true) {
			if (dt is MDArrayReferencedType mdArrayRefType) {
				arrayBuilder.append(mdArrayRefType.getArrayString());
				dt = mdArrayRefType.getReferencedType();
			}
			else if (dt is MDPointerType pointerType &&
				!pointerType.getCVMod().isFunctionPointerType()) {
				dt = pointerType.getReferencedType();
			}
			else {
				break;
			}
		}
		if ((refType is MDFunctionType) && (builder.length() > 0)) {
			((MDFunctionType) refType).setFromModifier();
		}
		dt.insert(builder);
		// Following is to clean the Based5 "bug" if seen.  See comments in MDBasedAttribute.
		dmang.cleanOutput(builder);
		dmang.appendString(builder, arrayBuilder.toString());
	}

}
